import{c as a,X as t,n as i,q as o,e as s,g as r}from"./chunks/framework.CboB3ZLJ.js";const g=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md"}'),l={name:"overview.md"};function n(d,e,c,m,h,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h1><p>Embedding Atlas is a tool that provides interactive visualizations for large embeddings and their metadata. You can visualize, cross-filter, and search across your data.</p><img style="border-radius:4px;margin-top:16px;" class="light-only" src="'+s+'"><img style="border-radius:4px;margin-top:16px;" class="dark-only" src="'+r+'"><p>While embeddings are the focus, Embedding Atlas also works as a dashboard for tabular data. If your dataset has no embedding column, the embedding view is hidden, but linked charts, full-text search, and the instances view still work. Supported column types include text, image, audio, numeric, categorical, and time.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to “What you can do”">​</a></h2><ul><li><strong>Explore embeddings.</strong> Visualize 2D projections of millions of points, browse automatic clusters and labels, find nearest neighbors, and cross-filter against metadata.</li><li><strong>Build dashboards.</strong> Standard charts (bar, line, bubble, count plot, eCDF) plus a composable chart spec for building custom charts. Configure cross-filtering between any of them. Works with or without an embedding column.</li><li><strong>Drive analysis with AI agents.</strong> The <a href="./tool.html">command line tool</a> includes an <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">MCP</a> server. Agents can query the schema, run SQL, create and modify charts, and capture screenshots.</li><li><strong>Work with multimodal data.</strong> Text, image, and audio columns are rendered with appropriate viewers; time columns get time-aware charts.</li></ul><p>See <a href="./examples/">Examples</a> for live demos with embedding and tabular datasets.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>You can use Embedding Atlas directly from this website by <a href="https://apple.github.io/embedding-atlas/app/" target="_blank" rel="noreferrer">loading your own data</a>. In this online version, Embedding Atlas will compute the embedding and projection in your browser. Your data does not leave your machine.</p></div><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to “Packages”">​</a></h2><p>Embedding Atlas is released as two packages:</p><ul><li><p>A Python package <code>embedding-atlas</code> that provides:</p><ul><li>A <a href="./tool.html">command-line tool</a> for launching Embedding Atlas from the command line.</li><li>A <a href="./widget.html">Python Notebook widget</a> for using Embedding Atlas in interactive Python notebooks.</li><li>A <a href="./streamlit.html">Streamlit component</a> for using Embedding Atlas in Streamlit apps.</li><li>All of these approaches allow you to compute embeddings (with custom models) and projections.</li></ul></li><li><p>An npm package <code>embedding-atlas</code> that exposes the user interface components as APIs so you can use them in your own applications. Below are the exposed components:</p><ul><li><a href="./embedding-view.html">EmbeddingView</a></li><li><a href="./embedding-view-mosaic.html">EmbeddingViewMosaic</a></li><li><a href="./embedding-atlas.html">EmbeddingAtlas</a></li><li><a href="./algorithms.html">Algorithms</a></li></ul></li></ul>',12)])])}const b=a(l,[["render",n]]);export{g as __pageData,b as default};
